// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlusJakartaSans = makeLoadFont('PlusJakartaSans');
const loadInter = makeLoadFont('Inter');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: plusJakartaSansFamily } = loadPlusJakartaSans();
const { fontFamily: interFamily } = loadInter();



export type ComponentNameProps = Record<string, any>;

const ComponentName: React.FC<ComponentNameProps> = ({
  backgroundColor = "#F8F7F4",
  transparentBackground = false,
  durationInSeconds = 8,
  titleLine1 = "Liasing",
  titleLine2 = "with",
  titleLine3 = "Suppliers",
  titleLine4 = "in Hong Kong",
  titleColor = "#0D1424",
  highlightColor = "#FF463B",
  accentColor = "#FF463B",
  sunColor = "#FF463B",
  sunRadiusPercent = 72,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background color transparency logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Global layout parameters (Optimized for 9:16)
  const waterY = height * 0.72;
  const skylineX = 0;
  const skylineWidth = width;

  // Title Animation (Staggered snap slides)
  const l1Progress = spring({ frame: frame - 10, fps, config: { damping: 15, mass: 0.8 } });
  const l2Progress = spring({ frame: frame - 14, fps, config: { damping: 15, mass: 0.8 } });
  const l3Progress = spring({ frame: frame - 18, fps, config: { damping: 15, mass: 0.8 } });
  const l4Progress = spring({ frame: frame - 22, fps, config: { damping: 15, mass: 0.8 } });

  const l1X = interpolate(l1Progress, [0, 1], [-50, 0]);
  const l2X = interpolate(l2Progress, [0, 1], [-50, 0]);
  const l3X = interpolate(l3Progress, [0, 1], [-50, 0]);
  const l4X = interpolate(l4Progress, [0, 1], [-50, 0]);

  // Red Sun Animation (Elastic scale + float)
  const sunProgress = spring({ frame: frame - 5, fps, config: { damping: 14, mass: 1.2 } });
  const sunScale = interpolate(sunProgress, [0, 1], [0, 1], { extrapolateRight: "clamp" });
  const sunYOffset = Math.sin(frame * 0.04) * 8; // Gentle floating movement

  // Skyline Building Data Setup
  const buildingSpecs = [
    { id: "b1", leftPct: 2, widthPct: 7, heightPct: 25, type: "flat", stagger: 0 },
    { id: "b2", leftPct: 10, widthPct: 6, heightPct: 35, type: "flat", stagger: 3 },
    { id: "b3", leftPct: 17, widthPct: 8, heightPct: 40, type: "flat", stagger: 6 },
    { id: "b4", leftPct: 26, widthPct: 7, heightPct: 30, type: "flat", stagger: 2 },
    { id: "boc", leftPct: 34, widthPct: 9, heightPct: 55, type: "boc", stagger: 8 }, // Bank of China
    { id: "b5", leftPct: 44, widthPct: 8, heightPct: 42, type: "flat", stagger: 4 },
    { id: "b6", leftPct: 53, widthPct: 7, heightPct: 35, type: "flat", stagger: 9 },
    { id: "b7", leftPct: 61, widthPct: 8, heightPct: 48, type: "flat", stagger: 5 },
    { id: "b8", leftPct: 70, widthPct: 7, heightPct: 38, type: "flat", stagger: 10 },
    { id: "ifc", leftPct: 78, widthPct: 10, heightPct: 72, type: "ifc", stagger: 12 }, // IFC Tower
    { id: "b9", leftPct: 89, widthPct: 8, heightPct: 28, type: "flat", stagger: 7 },
  ];

  // Mountain background animation
  const mountainProgress = spring({ frame: frame - 8, fps, config: { damping: 16 } });
  const mountainY = interpolate(mountainProgress, [0, 1], [waterY + 120, waterY], { extrapolateRight: "clamp" });

  // Diagonal Crop Wedge
  const wedgeProgress = spring({ frame: frame - 28, fps, config: { damping: 16, mass: 1.1 } });
  const wedgeTranslateX = (1 - wedgeProgress) * 350;
  const wedgeTranslateY = (1 - wedgeProgress) * 350;

  // Connective line details
  const lineProgress = interpolate(frame, [40, 72], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const lineMaxWidth = width * 0.3;
  const currentLineLength = lineProgress * lineMaxWidth;

  // Dot Matrix calculations
  const dotRows = 4;
  const dotCols = 8;

  // Water ripples data mapping
  const ripples = Array.from({ length: 8 }).map((_, i) => {
    const yPos = waterY + (height - waterY) * ((i + 1) / 9);
    return { y: yPos, delay: i * 4 };
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {/* LEFT CONTENT AREA */}
      <div
        style={{
          position: "absolute",
          top: height * 0.16,
          left: width * 0.08,
          display: "flex",
          flexDirection: "column",
          gap: height * 0.008,
          fontFamily: plusJakartaSansFamily,
          fontWeight: 800,
          fontSize: width * 0.11,
          lineHeight: 1.05,
          color: titleColor,
          zIndex: 10,
          transition: "none",
        }}
      >
        <div style={{ transform: `translateX(${l1X}px)`, opacity: l1Progress, transition: "none" }}>
          {titleLine1}
        </div>
        <div style={{ transform: `translateX(${l2X}px)`, opacity: l2Progress, transition: "none" }}>
          {titleLine2}
        </div>
        <div style={{ transform: `translateX(${l3X}px)`, opacity: l3Progress, transition: "none" }}>
          {titleLine3}
        </div>
        <div style={{ transform: `translateX(${l4X}px)`, opacity: l4Progress, color: highlightColor, transition: "none" }}>
          {titleLine4}
        </div>
      </div>

      {/* TOP-LEFT ACCENT SQUARE */}
      {(() => {
        const sq1Progress = spring({ frame: frame - 24, fps, config: { damping: 12 } });
        return (
          <div
            style={{
              position: "absolute",
              top: height * 0.08,
              left: width * 0.08,
              width: Math.min(width, height) * 0.05,
              height: Math.min(width, height) * 0.05,
              backgroundColor: accentColor,
              transform: `scale(${sq1Progress}) rotate(${sq1Progress * 90}deg)`,
              opacity: sq1Progress,
              transition: "none",
            }}
          />
        );
      })()}

      {/* BOTTOM-LEFT DOTS GRID */}
      <div
        style={{
          position: "absolute",
          top: height * 0.62,
          left: width * 0.08,
          display: "grid",
          gridTemplateColumns: `repeat(${dotCols}, 1fr)`,
          gap: 10,
          transition: "none",
          zIndex: 5,
        }}
      >
        {Array.from({ length: dotRows * dotCols }).map((_, idx) => {
          const r = Math.floor(idx / dotCols);
          const c = idx % dotCols;
          const dotDelay = 30 + r * 2.5 + c * 1.5;
          const dotProgress = spring({ frame: frame - dotDelay, fps, config: { damping: 12 } });
          return (
            <div
              key={idx}
              style={{
                width: 4,
                height: 4,
                borderRadius: "50%",
                backgroundColor: titleColor,
                opacity: dotProgress * 0.35,
                transform: `scale(${dotProgress})`,
                transition: "none",
              }}
            />
          );
        })}
      </div>

      {/* HORIZONTAL CONNECTOR ACCENT LINE */}
      <div
        style={{
          position: "absolute",
          top: height * 0.68,
          left: width * 0.2,
          width: currentLineLength,
          height: 1.5,
          backgroundColor: titleColor,
          opacity: Math.min(0.25, lineProgress),
          transition: "none",
        }}
      />

      {/* BOTTOM-LEFT SLIDING ACCENT SQUARE */}
      {(() => {
        const sq2Progress = spring({ frame: frame - 48, fps, config: { damping: 14 } });
        const size = Math.min(width, height) * 0.05;
        return (
          <div
            style={{
              position: "absolute",
              top: height * 0.68 - size / 2,
              left: width * 0.2 + currentLineLength,
              width: size,
              height: size,
              backgroundColor: accentColor,
              transform: `scale(${sq2Progress}) rotate(${sq2Progress * -90}deg)`,
              opacity: sq2Progress,
              transition: "none",
            }}
          />
        );
      })()}

      {/* RIGHT GRAPHICS CONTAINER */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: skylineX,
          width: skylineWidth,
          height: height,
          overflow: "hidden",
          transition: "none",
        }}
      >
        {/* RED SUN BACKGROUND */}
        {(() => {
          const radius = (sunRadiusPercent / 100) * width * 0.45;
          return (
            <div
              style={{
                position: "absolute",
                top: height * 0.45 - radius + sunYOffset,
                left: skylineWidth * 0.5 - radius,
                width: radius * 2,
                height: radius * 2,
                borderRadius: "50%",
                backgroundColor: sunColor,
                transform: `scale(${sunScale})`,
                opacity: sunProgress,
                transition: "none",
              }}
            />
          );
        })()}

        {/* MOUNTAIN SILHOUETTE */}
        <svg
          style={{
            position: "absolute",
            top: mountainY - (height * 0.12),
            left: 0,
            width: "100%",
            height: height * 0.12,
            overflow: "visible",
            opacity: mountainProgress * 0.45,
            transition: "none",
          }}
          viewBox="0 0 600 120"
          preserveAspectRatio="none"
        >
          <path
            d="M 0 120 L 0 85 Q 110 50 250 80 T 460 65 Q 530 80 600 70 L 600 120 Z"
            fill="#121A2A"
          />
        </svg>

        {/* WATER REFLECTION GRADIENT */}
        <div
          style={{
            position: "absolute",
            top: waterY,
            left: 0,
            width: "100%",
            height: height - waterY,
            background: `linear-gradient(to bottom, rgba(255, 255, 255, 0.45) 0%, ${backgroundColor} 90%)`,
            zIndex: 1,
            pointerEvents: "none",
            transition: "none",
          }}
        />

        {/* REAL BUILDINGS RISING */}
        {buildingSpecs.map((spec) => {
          const riseProgress = spring({
            frame: frame - (14 + spec.stagger),
            fps,
            config: { damping: 15, mass: 0.9 }
          });

          const bHeight = (spec.heightPct / 100) * height * 0.42;
          const bWidth = (spec.widthPct / 100) * skylineWidth;
          const bLeft = (spec.leftPct / 100) * skylineWidth;
          const ty = (1 - riseProgress) * bHeight;

          return (
            <div
              key={spec.id}
              style={{
                position: "absolute",
                bottom: height - waterY,
                left: bLeft,
                width: bWidth,
                height: bHeight,
                transform: `translateY(${ty}px)`,
                opacity: riseProgress,
                overflow: "hidden",
                transition: "none",
                zIndex: 2,
              }}
            >
              {spec.type === "boc" ? (
                <svg width="100%" height="100%" viewBox="0 0 100 100" preserveAspectRatio="none">
                  <polygon points="0,100 0,35 50,20 50,100" fill="#0D1424" />
                  <polygon points="50,100 50,20 100,35 100,100" fill="#1C273C" />
                  <line x1="0" y1="100" x2="100" y2="35" stroke="rgba(255,255,255,0.18)" strokeWidth="1" />
                  <line x1="100" y1="100" x2="0" y2="35" stroke="rgba(255,255,255,0.18)" strokeWidth="1" />
                  <line x1="0" y1="67" x2="100" y2="67" stroke="rgba(255,255,255,0.2)" strokeWidth="1" />
                  <line x1="0" y1="35" x2="100" y2="35" stroke="rgba(255,255,255,0.2)" strokeWidth="1" />
                  <line x1="50" y1="20" x2="50" y2="0" stroke="#0D1424" strokeWidth="2.5" />
                </svg>
              ) : spec.type === "ifc" ? (
                <svg width="100%" height="100%" viewBox="0 0 100 100" preserveAspectRatio="none">
                  <polygon points="12,100 18,15 50,6 82,15 88,100" fill="#0D1424" />
                  <polygon points="50,100 50,6 82,15 88,100" fill="#1E2B40" />
                  <line x1="28" y1="15" x2="28" y2="10" stroke="#0D1424" strokeWidth="1.5" />
                  <line x1="50" y1="6" x2="50" y2="0" stroke="#0D1424" strokeWidth="2.5" />
                  <line x1="72" y1="15" x2="72" y2="10" stroke="#1E2B40" strokeWidth="1.5" />
                  <line x1="32" y1="100" x2="35" y2="15" stroke="rgba(255,255,255,0.12)" strokeWidth="1" />
                  <line x1="50" y1="100" x2="50" y2="6" stroke="rgba(255,255,255,0.15)" strokeWidth="1.2" />
                  <line x1="68" y1="100" x2="65" y2="15" stroke="rgba(255,255,255,0.12)" strokeWidth="1" />
                </svg>
              ) : (
                <svg width="100%" height="100%" viewBox="0 0 100 100" preserveAspectRatio="none">
                  <rect x="0" y="0" width="50" height="100" fill="#0D1424" />
                  <rect x="50" y="0" width="50" height="100" fill="#1A2536" />
                  <line x1="25" y1="0" x2="25" y2="100" stroke="rgba(255, 255, 255, 0.12)" strokeWidth="1.5" strokeDasharray="3, 5" />
                  <line x1="75" y1="0" x2="75" y2="100" stroke="rgba(255, 255, 255, 0.12)" strokeWidth="1.5" strokeDasharray="3, 5" />
                </svg>
              )}
            </div>
          );
        })}

        {/* MIRRORED BUILDINGS FOR REFLECTION */}
        {buildingSpecs.map((spec) => {
          const riseProgress = spring({
            frame: frame - (14 + spec.stagger),
            fps,
            config: { damping: 15, mass: 0.9 }
          });

          const bHeight = (spec.heightPct / 100) * height * 0.42;
          const bWidth = (spec.widthPct / 100) * skylineWidth;
          const bLeft = (spec.leftPct / 100) * skylineWidth;
          const ty = (1 - riseProgress) * bHeight;

          return (
            <div
              key={`reflection-${spec.id}`}
              style={{
                position: "absolute",
                top: waterY,
                left: bLeft,
                width: bWidth,
                height: bHeight,
                transform: `scaleY(-1) translateY(${ty}px)`,
                opacity: riseProgress * 0.16,
                filter: "blur(1.5px)",
                overflow: "hidden",
                transition: "none",
                pointerEvents: "none",
                zIndex: 1,
              }}
            >
              {spec.type === "boc" ? (
                <svg width="100%" height="100%" viewBox="0 0 100 100" preserveAspectRatio="none">
                  <polygon points="0,100 0,35 50,20 50,100" fill="#0D1424" />
                  <polygon points="50,100 50,20 100,35 100,100" fill="#1C273C" />
                  <line x1="0" y1="100" x2="100" y2="35" stroke="rgba(255,255,255,0.18)" strokeWidth="1" />
                  <line x1="100" y1="100" x2="0" y2="35" stroke="rgba(255,255,255,0.18)" strokeWidth="1" />
                </svg>
              ) : spec.type === "ifc" ? (
                <svg width="100%" height="100%" viewBox="0 0 100 100" preserveAspectRatio="none">
                  <polygon points="12,100 18,15 50,6 82,15 88,100" fill="#0D1424" />
                  <polygon points="50,100 50,6 82,15 88,100" fill="#1E2B40" />
                </svg>
              ) : (
                <svg width="100%" height="100%" viewBox="0 0 100 100" preserveAspectRatio="none">
                  <rect x="0" y="0" width="50" height="100" fill="#0D1424" />
                  <rect x="50" y="0" width="50" height="100" fill="#1A2536" />
                </svg>
              )}
            </div>
          );
        })}

        {/* WATER SHIMMER RIPPLE LINES */}
        {ripples.map((ripple, idx) => {
          const shimmer = Math.sin(frame * 0.08 + ripple.delay);
          const rippleScale = interpolate(shimmer, [-1, 1], [0.85, 1.15]);
          const rippleOpacity = interpolate(shimmer, [-1, 1], [0.06, 0.22]);
          return (
            <div
              key={idx}
              style={{
                position: "absolute",
                top: ripple.y,
                left: 0,
                width: "100%",
                height: 1.5,
                backgroundColor: titleColor,
                opacity: rippleOpacity,
                transform: `scaleX(${rippleScale})`,
                transformOrigin: "center",
                transition: "none",
                zIndex: 3,
                pointerEvents: "none",
              }}
            />
          );
        })}

        {/* DIAGONAL CROP WEDGE */}
        <svg
          style={{
            position: "absolute",
            bottom: 0,
            right: 0,
            width: skylineWidth * 0.45,
            height: height * 0.2,
            transform: `translate(${wedgeTranslateX}px, ${wedgeTranslateY}px)`,
            overflow: "visible",
            zIndex: 4,
            transition: "none",
          }}
          viewBox="0 0 100 100"
          preserveAspectRatio="none"
        >
          <polygon points="100,0 0,100 100,100" fill={titleColor} />
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default ComponentName;